from flask import jsonify
from werkzeug.exceptions import HTTPException


class APIError(Exception):
    status_code = 400

    def __init__(self, message, status_code=None, details=None):
        super().__init__(message)
        self.message = message
        if status_code is not None:
            self.status_code = status_code
        self.details = details


class ValidationError(APIError):
    status_code = 422


class AuthError(APIError):
    status_code = 401


class ForbiddenError(APIError):
    status_code = 403


class NotFoundError(APIError):
    status_code = 404


class ConflictError(APIError):
    status_code = 409


class RateLimitError(APIError):
    status_code = 429

    def __init__(self, message="rate limit exceeded", retry_after=None):
        super().__init__(message)
        self.retry_after = retry_after


def _payload(message, details=None):
    body = {"error": message}
    if details:
        body["details"] = details
    return body


def register_error_handlers(app):
    @app.errorhandler(APIError)
    def handle_api_error(e):
        resp = jsonify(_payload(e.message, e.details))
        resp.status_code = e.status_code
        if isinstance(e, RateLimitError) and e.retry_after is not None:
            resp.headers["Retry-After"] = str(e.retry_after)
        return resp

    @app.errorhandler(HTTPException)
    def handle_http_error(e):
        return jsonify(_payload(e.description or e.name)), e.code

    @app.errorhandler(Exception)
    def handle_unexpected(e):
        return jsonify(_payload("internal server error")), 500

import uuid
from datetime import datetime, timedelta, timezone
from functools import wraps
import jwt
from flask import current_app, g, request
from .extensions import db
from .models import RefreshToken, User
from .errors import AuthError


def _now():
    return datetime.now(timezone.utc)


def create_access_token(user):
    payload = {
        "sub": str(user.id),
        "type": "access",
        "iat": _now(),
        "exp": _now() + timedelta(seconds=current_app.config["JWT_ACCESS_TTL"]),
        "jti": uuid.uuid4().hex,
    }
    return jwt.encode(payload, current_app.config["SECRET_KEY"], algorithm="HS256")


def create_refresh_token(user):
    jti = uuid.uuid4().hex
    exp = _now() + timedelta(seconds=current_app.config["JWT_REFRESH_TTL"])
    db.session.add(RefreshToken(jti=jti, user_id=user.id, expires_at=exp.replace(tzinfo=None)))
    db.session.commit()
    payload = {"sub": str(user.id), "type": "refresh", "iat": _now(), "exp": exp, "jti": jti}
    return jwt.encode(payload, current_app.config["SECRET_KEY"], algorithm="HS256")


def decode_token(token, expected_type):
    try:
        payload = jwt.decode(token, current_app.config["SECRET_KEY"], algorithms=["HS256"])
    except jwt.ExpiredSignatureError:
        raise AuthError("token expired")
    except jwt.InvalidTokenError:
        raise AuthError("invalid token")
    if payload.get("type") != expected_type:
        raise AuthError("invalid token type")
    return payload


def rotate_refresh_token(token):
    payload = decode_token(token, "refresh")
    record = RefreshToken.query.filter_by(jti=payload["jti"]).first()
    if record is None or record.revoked:
        raise AuthError("refresh token revoked or unknown")
    record.revoked = True
    user = db.session.get(User, int(payload["sub"]))
    if user is None:
        raise AuthError("user not found")
    return user


def revoke_refresh_token(token):
    payload = decode_token(token, "refresh")
    record = RefreshToken.query.filter_by(jti=payload["jti"]).first()
    if record is None or record.revoked:
        raise AuthError("refresh token revoked or unknown")
    record.revoked = True
    db.session.commit()


def require_auth(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        header = request.headers.get("Authorization", "")
        if not header.startswith("Bearer "):
            raise AuthError("missing or malformed Authorization header")
        payload = decode_token(header[7:], "access")
        user = db.session.get(User, int(payload["sub"]))
        if user is None:
            raise AuthError("user not found")
        g.current_user = user
        return f(*args, **kwargs)
    return wrapper

import time
from collections import defaultdict, deque
from functools import wraps
from flask import current_app, request
from .errors import RateLimitError

_buckets = defaultdict(deque)


def reset():
    _buckets.clear()


def rate_limit(key_prefix, max_config, window_config):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            limit = current_app.config[max_config]
            window = current_app.config[window_config]
            key = f"{key_prefix}:{request.remote_addr}"
            now = time.monotonic()
            bucket = _buckets[key]
            while bucket and bucket[0] <= now - window:
                bucket.popleft()
            if len(bucket) >= limit:
                retry = int(window - (now - bucket[0])) + 1
                raise RateLimitError(retry_after=retry)
            bucket.append(now)
            return f(*args, **kwargs)
        return wrapper
    return decorator

import re
from flask import request
from .errors import ValidationError

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
USERNAME_RE = re.compile(r"^[a-zA-Z0-9_]{3,80}$")


def get_json_body():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        raise ValidationError("request body must be a JSON object")
    return data


def validate(data, schema):
    errors = {}
    out = {}
    for field, rules in schema.items():
        value = data.get(field)
        if value is None:
            if rules.get("required"):
                errors[field] = "is required"
            elif "default" in rules:
                out[field] = rules["default"]
            continue
        typ = rules.get("type", str)
        if not isinstance(value, typ) or (typ is str and isinstance(value, bool)):
            errors[field] = f"must be of type {typ.__name__}"
            continue
        if typ is str:
            value = value.strip()
            if rules.get("min_len") and len(value) < rules["min_len"]:
                errors[field] = f"must be at least {rules['min_len']} characters"
                continue
            if rules.get("max_len") and len(value) > rules["max_len"]:
                errors[field] = f"must be at most {rules['max_len']} characters"
                continue
            if rules.get("regex") and not rules["regex"].match(value):
                errors[field] = rules.get("regex_msg", "has invalid format")
                continue
        out[field] = value
    unknown = set(data) - set(schema)
    for field in unknown:
        errors[field] = "unknown field"
    if errors:
        raise ValidationError("validation failed", details=errors)
    return out


def parse_pagination():
    try:
        page = int(request.args.get("page", 1))
        per_page = int(request.args.get("per_page", 20))
    except (TypeError, ValueError):
        raise ValidationError("page and per_page must be integers")
    if page < 1:
        raise ValidationError("page must be >= 1")
    if per_page < 1 or per_page > 100:
        raise ValidationError("per_page must be between 1 and 100")
    return page, per_page
